using System;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        int i = 0;

        if (Vector512.IsHardwareAccelerated && data.Length >= Vector512<int>.Count)
        {
            var vThreshold = Vector512.Create(threshold);
            var vOne = Vector512.Create(1);
            var vectors = MemoryMarshal.Cast<int, Vector512<int>>(data);

            for (int vi = 0; vi < vectors.Length; vi++)
            {
                var mask = Vector512.GreaterThan(vectors[vi], vThreshold);
                vectors[vi] += vOne & mask;
            }

            i = vectors.Length * Vector512<int>.Count;
        }
        else if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<int>.Count)
        {
            var vThreshold = Vector256.Create(threshold);
            var vOne = Vector256.Create(1);
            var vectors = MemoryMarshal.Cast<int, Vector256<int>>(data);

            for (int vi = 0; vi < vectors.Length; vi++)
            {
                var mask = Vector256.GreaterThan(vectors[vi], vThreshold);
                vectors[vi] += vOne & mask;
            }

            i = vectors.Length * Vector256<int>.Count;
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<int>.Count)
        {
            var vThreshold = Vector128.Create(threshold);
            var vOne = Vector128.Create(1);
            var vectors = MemoryMarshal.Cast<int, Vector128<int>>(data);

            for (int vi = 0; vi < vectors.Length; vi++)
            {
                var mask = Vector128.GreaterThan(vectors[vi], vThreshold);
                vectors[vi] += vOne & mask;
            }

            i = vectors.Length * Vector128<int>.Count;
        }

        // Scalar tail
        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

